package servicio;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.util.List;import org.junit.jupiter.api.Test;import dao.IntentoPagoDAO;import negocio.*;
class IntentoPagoServiceTest {@Test void redactaSecretosYLimitaDetalle(){IntentoPagoDAO d=mock(IntentoPagoDAO.class);IntentoPagoService s=new IntentoPagoService(d);s.error(7,"access_token=abc123 password=secreto");verify(d).finalizar(eq(7L),eq(EstadoIntentoPago.ERROR),isNull(),argThat(x->x.contains("[REDACTADO]")&&!x.contains("abc123")&&!x.contains("secreto")&&x.length()<=500));}@Test void delegaInicioEHistorial(){IntentoPagoDAO d=mock(IntentoPagoDAO.class);IntentoPago i=new IntentoPago();when(d.iniciar(3)).thenReturn(i);when(d.listarPorOrden(3)).thenReturn(List.of(i));IntentoPagoService s=new IntentoPagoService(d);assertSame(i,s.iniciar(3));assertEquals(1,s.listar(3).size());}}
